import { gridDistance } from 'h3-js'
import type { Driver, DriverStatus } from '../domain'
import { h3CellForPoint, h3DiskForPoint, type GeoPoint } from './h3-index'

const ACTIVE_ASSIGNMENT_STATUSES: DriverStatus[] = ['Disponible']
const DEFAULT_MAX_LOCATION_AGE_MS = 120_000
const DEFAULT_MAX_RING = 2

export interface DriverLiveLocation extends GeoPoint {
  updatedAt: number
}

export interface DriverCandidate {
  driver: Driver
  ring: number | null
  distanceKm: number | null
}

export interface DriverCandidateSelection {
  candidates: DriverCandidate[]
  usedFallback: boolean
}

export interface SelectDriverCandidatesInput {
  origin?: GeoPoint
  drivers: Driver[]
  liveLocations: Map<string, DriverLiveLocation>
  preferredNames?: string[]
  maxRing?: number
  maxLocationAgeMs?: number
  isCompatible?: (driver: Driver) => boolean
}

function distanceKm(a: GeoPoint, b: GeoPoint) {
  const earthRadiusKm = 6371
  const toRadians = (value: number) => value * Math.PI / 180
  const latitudeDelta = toRadians(b.latitude - a.latitude)
  const longitudeDelta = toRadians(b.longitude - a.longitude)
  const latitudeA = toRadians(a.latitude)
  const latitudeB = toRadians(b.latitude)
  const haversine = Math.sin(latitudeDelta / 2) ** 2
    + Math.cos(latitudeA) * Math.cos(latitudeB) * Math.sin(longitudeDelta / 2) ** 2
  return 2 * earthRadiusKm * Math.asin(Math.sqrt(haversine))
}

function isFresh(location: DriverLiveLocation, maxAgeMs: number) {
  return Number.isFinite(location.updatedAt) && Date.now() - location.updatedAt <= maxAgeMs
}

function fallbackCandidates(drivers: Driver[], preferredNames: string[]): DriverCandidate[] {
  const preferred = new Map(preferredNames.map((name, index) => [name.toLowerCase(), index]))
  return drivers
    .map((driver) => ({ driver, ring: null, distanceKm: null }))
    .sort((a, b) => (preferred.get(a.driver.name.toLowerCase()) ?? Number.MAX_SAFE_INTEGER) - (preferred.get(b.driver.name.toLowerCase()) ?? Number.MAX_SAFE_INTEGER))
}

export function selectDriverCandidates(input: SelectDriverCandidatesInput): DriverCandidateSelection {
  const preferredNames = input.preferredNames ?? []
  const available = input.drivers.filter((driver) => ACTIVE_ASSIGNMENT_STATUSES.includes(driver.status) && (input.isCompatible?.(driver) ?? true))
  if (!input.origin || available.length === 0) {
    return { candidates: fallbackCandidates(available, preferredNames), usedFallback: true }
  }

  const maxAgeMs = input.maxLocationAgeMs ?? DEFAULT_MAX_LOCATION_AGE_MS
  const maxRing = input.maxRing ?? DEFAULT_MAX_RING
  const originCell = h3CellForPoint(input.origin)
  const cells = new Set(h3DiskForPoint(input.origin, maxRing))
  const preferred = new Map(preferredNames.map((name, index) => [name.toLowerCase(), index]))
  const spatialCandidates: DriverCandidate[] = []

  for (const driver of available) {
    const location = input.liveLocations.get(driver.name)
    if (!location || !isFresh(location, maxAgeMs)) continue
    const driverCell = h3CellForPoint(location)
    if (!cells.has(driverCell)) continue
    let ring: number
    try {
      ring = gridDistance(originCell, driverCell)
    } catch {
      ring = maxRing
    }
    spatialCandidates.push({
      driver,
      ring,
      distanceKm: distanceKm(input.origin, location),
    })
  }

  if (spatialCandidates.length === 0) {
    return { candidates: fallbackCandidates(available, preferredNames), usedFallback: true }
  }

  spatialCandidates.sort((a, b) => {
    if (a.ring !== b.ring) return a.ring! - b.ring!
    if (a.distanceKm !== b.distanceKm) return a.distanceKm! - b.distanceKm!
    return (preferred.get(a.driver.name.toLowerCase()) ?? Number.MAX_SAFE_INTEGER) - (preferred.get(b.driver.name.toLowerCase()) ?? Number.MAX_SAFE_INTEGER)
  })
  return { candidates: spatialCandidates, usedFallback: false }
}
